Class NovaShaders Namespace Nova.Avalonia.Animations.Shaders Assembly Nova.Avalonia.Animations.Shaders.dll Provides the built-in SkSL effects used by Nova shader controls. public static class NovaShaders Inheritance object NovaShaders Inherited Members object.Equals(object) object.Equals(object, object) object.GetHashCode() object.GetType() object.MemberwiseClone() object.ReferenceEquals(object, object) object.ToString() Remarks A shader may declare any of these uniforms and ShaderView sets only the ones it declares: iTime in seconds; iResolution, iPointer, and iClick in control coordinates; and iProgress and iPress from zero to one. Progress and press can be driven with Nova springs. Fields AuroraRipple Apple-Intelligence-style effect: aurora background, pointer glow, and an expanding ripple ring driven by iProgress (animate it with a Nova spring). public const string AuroraRipple = "uniform float iTime;
uniform float2 iResolution;
uniform float2 iPointer;
uniform float iProgress;

half4 main(float2 fragCoord) {
 float2 uv = fragCoord / iResolution;
 float aspect = iResolution.x / max(iResolution.y, 1.0);
 float2 pos = float2(uv.x * aspect, uv.y);
 float2 ptr = float2(iPointer.x / iResolution.x * aspect, iPointer.y / iResolution.y);

 float d = distance(pos, ptr);

 float t = iTime * 0.35;
 half3 color = half3(
 half(0.16 + 0.10 * sin(6.28318 * (uv.x * 0.7 + t))),
 half(0.10 + 0.09 * sin(6.28318 * (uv.y * 0.6 + t + 0.33))),
 half(0.26 + 0.14 * sin(6.28318 * ((uv.x + uv.y) * 0.5 + t + 0.66))));

 color += half3(0.30, 0.18, 0.52) * half(exp(-d * 6.0));

 // Swell in quickly, then fade out before the end so nothing is left frozen on screen.
 // Written with clamp rather than smoothstep, which this SkSL dialect does not provide.
 float rise = clamp(iProgress / 0.12, 0.0, 1.0);
 float fall = clamp((1.0 - iProgress) / 0.45, 0.0, 1.0);
 float envelope = rise * rise * (3.0 - 2.0 * rise) * fall * fall * (3.0 - 2.0 * fall);

 float radius = iProgress * 1.6;
 float ring = exp(-pow((d - radius) * 9.0, 2.0));
 float wave = sin(d * 45.0 - iProgress * 22.0) * exp(-d * 2.5);
 color += half3(0.85, 0.80, 1.00) * half(ring * 0.9 * envelope);
 color += half3(half(wave * 0.18 * envelope));

 return half4(color, 1.0);
}" Field Value string BackdropBlur A live backdrop blur without the tint, for dimming content behind a panel. public const string BackdropBlur = "uniform shader iContent;
uniform float2 iResolution;
uniform float2 iOffset;
uniform float iProgress;

half4 main(float2 fragCoord) {
 float2 source = fragCoord + iOffset;
 float radius = 1.0 + iProgress * 14.0;

 half4 sum = iContent.eval(source) * 4.0;
 sum += iContent.eval(source + float2( radius, 0)) * 2.0;
 sum += iContent.eval(source + float2(-radius, 0)) * 2.0;
 sum += iContent.eval(source + float2(0, radius)) * 2.0;
 sum += iContent.eval(source + float2(0, -radius)) * 2.0;
 sum += iContent.eval(source + float2( radius, radius) * 0.7);
 sum += iContent.eval(source + float2(-radius, radius) * 0.7);
 sum += iContent.eval(source + float2( radius, -radius) * 0.7);
 sum += iContent.eval(source + float2(-radius, -radius) * 0.7);

 return sum / 16.0;
}" Field Value string ClickRipple A ripple starting exactly where the pointer went down. Animate iProgress 0 to 1 per press; iClick holds the origin still while it expands. public const string ClickRipple = "uniform float2 iResolution;
uniform float2 iClick;
uniform float iProgress;

half4 main(float2 fragCoord) {
 float2 uv = fragCoord / iResolution;
 float aspect = iResolution.x / max(iResolution.y, 1.0);
 float2 pos = float2(uv.x * aspect, uv.y);
 float2 origin = float2(iClick.x / iResolution.x * aspect, iClick.y / iResolution.y);

 float d = distance(pos, origin);
 float radius = iProgress * 1.9;

 // Fade both ends to avoid a persistent point at progress zero.
 float rise = clamp(iProgress / 0.06, 0.0, 1.0);
 float fall = clamp((1.0 - iProgress) / 0.5, 0.0, 1.0);
 float envelope = rise * fall * fall * (3.0 - 2.0 * fall);

 float disc = clamp((radius - d) * 12.0, 0.0, 1.0);
 float edge = exp(-pow((d - radius) * 14.0, 2.0));

 half3 base = half3(0.09, 0.10, 0.15);
 half3 fill = half3(0.42, 0.36, 0.95);
 half3 color = mix(base, fill, half(disc * envelope * 0.85));
 color += half3(0.85, 0.82, 1.00) * half(edge * envelope * 0.7);
 return half4(color, 1.0);
}" Field Value string Dissolve Transition effects sample a captured frame of real UI through iContent. Use them with ShaderTransition, which supplies the snapshot. public const string Dissolve = "uniform shader iContent;
uniform float2 iResolution;
uniform float iProgress;

float noise(float2 p) {
 return fract(sin(dot(p, float2(12.9898, 78.233))) * 43758.5453);
}

half4 main(float2 fragCoord) {
 half4 source = iContent.eval(fragCoord);

 // Per-pixel thresholds produce a grain dissolve.
 float threshold = noise(floor(fragCoord / 3.0));
 float alpha = clamp((1.0 - iProgress) * 1.35 - threshold * 0.35, 0.0, 1.0);
 return source * half(alpha);
}" Field Value string Foil Holographic foil whose hue shifts with the pointer, like a trading card. public const string Foil = "uniform float iTime;
uniform float2 iResolution;
uniform float2 iPointer;

half3 hue(float h) {
 float3 k = float3(1.0, 0.6666667, 0.3333333);
 float3 p = abs(fract(float3(h, h, h) + k) * 6.0 - 3.0);
 return half3(clamp(p - 1.0, 0.0, 1.0));
}

half4 main(float2 fragCoord) {
 float2 uv = fragCoord / iResolution;
 float2 ptr = iPointer / iResolution;

 float2 delta = uv - ptr;
 float dist = length(delta);

 // Two-argument atan is not available here, so the hue is driven by the direction
 // components directly. It gives the same tilt-to-shift feel without the angle.
 float tilt = (delta.x - delta.y) * 0.5;

 float bands = sin((uv.x + uv.y) * 14.0 + iTime * 0.6) * 0.5 + 0.5;
 float h = fract(tilt + dist * 0.9 + bands * 0.15 + iTime * 0.03);

 half3 color = hue(h) * half(0.55 + 0.45 * bands);
 color *= half(0.35 + 0.75 * exp(-dist * 1.6));
 return half4(color, 1.0);
}" Field Value string Glass Creates a frosted-glass effect over live content. public const string Glass = "uniform shader iContent;
uniform float2 iResolution;
uniform float2 iOffset;
uniform float iProgress;

half4 main(float2 fragCoord) {
 float2 source = fragCoord + iOffset;
 float radius = 3.0 + iProgress * 11.0;

 // A weighted 3x3 kernel avoids visible duplicate silhouettes without adding samples.
 half4 sum = iContent.eval(source) * 4.0;
 sum += iContent.eval(source + float2( radius, 0)) * 2.0;
 sum += iContent.eval(source + float2(-radius, 0)) * 2.0;
 sum += iContent.eval(source + float2(0, radius)) * 2.0;
 sum += iContent.eval(source + float2(0, -radius)) * 2.0;
 sum += iContent.eval(source + float2( radius, radius) * 0.7);
 sum += iContent.eval(source + float2(-radius, radius) * 0.7);
 sum += iContent.eval(source + float2( radius, -radius) * 0.7);
 sum += iContent.eval(source + float2(-radius, -radius) * 0.7);

 half4 blurred = sum / 16.0;

 // Lift and desaturate slightly so text stays readable on top.
 half3 tinted = mix(blurred.rgb, half3(1.0, 1.0, 1.0), half(0.18));

 float2 uv = fragCoord / iResolution;
 float sheen = exp(-uv.y * 5.0) * 0.16;
 return half4(tinted + half3(half(sheen)), 1.0);
}" Field Value string Remarks The effect samples the backdrop with a small blur kernel, lightens it, and adds a top-edge highlight. Use it with ShaderBackdrop, which supplies the captured source and the offset that locates the panel within it. MeshGradient Slowly drifting mesh gradient, for hero or card backgrounds. public const string MeshGradient = "uniform float iTime;
uniform float2 iResolution;

half4 main(float2 fragCoord) {
 float2 uv = fragCoord / iResolution;
 float t = iTime * 0.18;

 float2 a = float2(0.25 + 0.18 * sin(t * 1.1), 0.30 + 0.16 * cos(t * 0.9));
 float2 b = float2(0.75 + 0.16 * cos(t * 0.8), 0.28 + 0.18 * sin(t * 1.3));
 float2 c = float2(0.40 + 0.20 * sin(t * 0.7), 0.78 + 0.14 * cos(t * 1.1));

 float wa = exp(-distance(uv, a) * 3.2);
 float wb = exp(-distance(uv, b) * 3.2);
 float wc = exp(-distance(uv, c) * 3.2);
 float sum = max(wa + wb + wc, 0.0001);

 half3 color = (half3(0.45, 0.36, 0.98) * half(wa)
 + half3(0.95, 0.42, 0.71) * half(wb)
 + half3(0.24, 0.78, 0.72) * half(wc)) / half(sum);

 return half4(color, 1.0);
}" Field Value string Pixelate Pixelates the captured frame as it leaves. public const string Pixelate = "uniform shader iContent;
uniform float2 iResolution;
uniform float iProgress;

half4 main(float2 fragCoord) {
 // Blocks grow with progress; the frame also fades so it does not end as colored squares.
 float size = 1.0 + iProgress * iProgress * 60.0;
 float2 snapped = (floor(fragCoord / size) + 0.5) * size;
 half4 source = iContent.eval(snapped);
 return source * half(clamp(1.0 - iProgress * 0.9, 0.0, 1.0));
}" Field Value string PressGlow A glow that swells while the pointer is held. Drive iPress with a spring. public const string PressGlow = "uniform float iTime;
uniform float2 iResolution;
uniform float2 iPointer;
uniform float iPress;

half4 main(float2 fragCoord) {
 float2 uv = fragCoord / iResolution;
 float aspect = iResolution.x / max(iResolution.y, 1.0);
 float2 pos = float2(uv.x * aspect, uv.y);
 float2 ptr = float2(iPointer.x / iResolution.x * aspect, iPointer.y / iResolution.y);

 float d = distance(pos, ptr);
 float pulse = 0.9 + 0.1 * sin(iTime * 6.0);
 float glow = exp(-d * (7.0 - iPress * 3.5)) * iPress * pulse;

 half3 base = half3(0.07, 0.08, 0.12);
 half3 color = base + half3(0.55, 0.40, 1.00) * half(glow);
 color += half3(1.0, 0.95, 0.85) * half(exp(-d * 26.0) * iPress);
 return half4(color, 1.0);
}" Field Value string Shimmer Skeleton shimmer: a highlight sweeping across a loading placeholder. It loops on iTime, so it needs no animation state of its own. public const string Shimmer = "uniform float iTime;
uniform float2 iResolution;

half4 main(float2 fragCoord) {
 float2 uv = fragCoord / iResolution;

 // The sweep runs on a diagonal and repeats with a pause between passes.
 float cycle = fract(iTime * 0.6);
 float head = cycle * 2.2 - 0.6;
 float band = (uv.x + uv.y * 0.35) - head;
 float sweep = exp(-band * band * 26.0);

 float alpha = 0.07 + 0.22 * sweep;
 return half4(half3(1.0) * half(alpha), half(alpha));
}" Field Value string Spotlight A spotlight that follows the pointer and widens while held down. public const string Spotlight = "uniform float2 iResolution;
uniform float2 iPointer;
uniform float iPress;

half4 main(float2 fragCoord) {
 float2 uv = fragCoord / iResolution;
 float aspect = iResolution.x / max(iResolution.y, 1.0);
 float2 pos = float2(uv.x * aspect, uv.y);
 float2 ptr = float2(iPointer.x / iResolution.x * aspect, iPointer.y / iResolution.y);

 float radius = 0.18 + iPress * 0.14;
 float d = distance(pos, ptr);
 float beam = exp(-pow(d / radius, 2.0));

 half3 warm = half3(1.00, 0.94, 0.78);
 half3 cool = half3(0.05, 0.06, 0.10);
 half3 color = mix(cool, warm, half(beam));

 // A faint rim keeps the edge of the beam readable on dark ground.
 color += half3(0.20, 0.18, 0.30) * half(exp(-pow((d - radius) * 7.0, 2.0)) * 0.5);
 return half4(color, 1.0);
}" Field Value string Wipe A diagonal wipe with a bright leading edge, the classic curtain transition. public const string Wipe = "uniform shader iContent;
uniform float2 iResolution;
uniform float iProgress;

half4 main(float2 fragCoord) {
 float2 uv = fragCoord / iResolution;
 half4 source = iContent.eval(fragCoord);

 float edge = (uv.x * 0.7 + uv.y * 0.3);
 float front = iProgress * 1.35 - 0.15;
 float alpha = clamp((edge - front) * 14.0, 0.0, 1.0);

 // Highlight the wipe boundary.
 float glow = exp(-pow((edge - front) * 16.0, 2.0)) * (1.0 - iProgress);
 return source * half(alpha) + half4(0.55, 0.50, 1.0, 0.0) * half(glow * 0.5);
}" Field Value string Properties All Every built-in effect, so tests can compile them all. public static IReadOnlyDictionary<string, string> All { get; } Property Value IReadOnlyDictionary<string, string> Transitions Effects that sample captured UI. They need a child shader, so they compile separately. public static IReadOnlyDictionary<string, string> Transitions { get; } Property Value IReadOnlyDictionary<string, string>
